// Qué contestar a cada mensaje. Cambiá los textos y las opciones por las de tu negocio.
const m = $json.message ?? {};
const elegido = m.choice?.id;
const texto = (m.text ?? '').toLowerCase();
const menu = { type: 'buttons', text: '¡Hola! ¿En qué te ayudo?', buttons: [
  { id: 'horarios', title: 'Horarios' },
  { id: 'precios', title: 'Precios' },
  { id: 'persona', title: 'Hablar con alguien' },
] };
let actions;
if (elegido === 'horarios' || texto.includes('horario')) {
  actions = [{ type: 'text', text: 'Abrimos de lunes a sábado, de 9 a 20.' }];
} else if (elegido === 'precios' || texto.includes('precio')) {
  actions = [{ type: 'list', text: 'Estos son nuestros precios:', button: 'Ver la lista', sections: [{ title: 'Servicios', rows: [
    { id: 'corte', title: 'Corte', description: '$12.000' },
    { id: 'color', title: 'Color', description: '$25.000' },
  ] }] }];
} else if (elegido === 'persona' || texto.includes('persona')) {
  // El negocio la ve en Atención, en el panel, y la contesta una persona.
  actions = [{ type: 'text', text: 'Te paso con alguien del equipo, ya te escribe.' }, { type: 'handoff', reason: 'Pidió hablar con una persona' }];
} else {
  actions = [menu];
}
return [{ json: { contractVersion: '0', actions } }];
